def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = {}
    for aid, opp in opponents_status.items():
        if opp.get('alive'):
            alive[aid] = opp

    if not alive:
        return float(min(budget, 18.0))

    threat_bid = 0.0
    threat_count = 0
    rich_threats = 0
    for aid, opp in alive.items():
        prev = opp.get('previous_trace', {})
        obudget = opp.get('budget', 0)
        ohp = opp.get('hp', 0)
        ono = opp.get('no_water_days', 0)
        req = opp.get('water_requirement', WATER_REQ)

        est = 0.0
        if prev and prev.get('bid') is not None:
            est = float(prev.get('bid', 0.0))
            if prev.get('status') not in ('ok', 'alive', 'won', 'lost', None):
                est = min(est, DAILY_SALARY * 0.4)
        else:
            est = DAILY_SALARY * 0.45

        if obudget <= 0:
            est = 0.0
        else:
            if ono >= 2 or ohp <= 2:
                est = max(est, DAILY_SALARY * 0.9)
            elif ono >= 1 or ohp <= 4:
                est = max(est, DAILY_SALARY * 0.7)

            if obudget < est:
                est = float(obudget)

        if est > 0:
            threat_count += 1
        if obudget >= DAILY_SALARY * 2:
            rich_threats += 1
        if est > threat_bid:
            threat_bid = est

    units = supply / float(WATER_REQ)
    tight = units < (1.0 + 0.15 * max(0, threat_count - 1))
    ample = units >= (1.5 + 0.2 * max(0, threat_count - 1))

    urgency = 0
    if hp <= 2 or no_water >= 2:
        urgency = 3
    elif hp <= 4 or no_water >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if urgency == 3:
        bid = max(DAILY_SALARY * 0.95, threat_bid + 3.0)
    elif urgency == 2:
        bid = max(DAILY_SALARY * 0.78, threat_bid + 2.0)
    else:
        if threat_count <= 1:
            if ample:
                bid = max(12.0, min(DAILY_SALARY * 0.38, threat_bid * 0.72))
            elif tight:
                bid = max(DAILY_SALARY * 0.52, threat_bid + 1.0)
            else:
                bid = max(DAILY_SALARY * 0.42, threat_bid * 0.82)
        else:
            if ample:
                bid = max(18.0, min(DAILY_SALARY * 0.48, threat_bid * 0.78))
            elif tight:
                bid = max(DAILY_SALARY * 0.7, threat_bid + 2.5)
            else:
                bid = max(DAILY_SALARY * 0.58, threat_bid + 1.0)

    if rich_threats == 0 and urgency == 0:
        bid = min(bid, DAILY_SALARY * 0.4)

    if day >= 8 and hp > 4 and no_water == 0:
        bid = min(bid, DAILY_SALARY * 0.5)

    reserve = 0.0
    if urgency == 0:
        reserve = DAILY_SALARY * 1.2
    elif urgency == 1:
        reserve = DAILY_SALARY * 0.8
    elif urgency == 2:
        reserve = DAILY_SALARY * 0.3

    max_affordable = budget - reserve
    if max_affordable <= 0:
        max_affordable = budget * 0.6

    bid = min(bid, budget, max_affordable)

    if urgency >= 2 and bid < min(budget, DAILY_SALARY * 0.72):
        bid = min(budget, DAILY_SALARY * 0.72)

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    my_hp = float(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids for immediate reaction
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass
        if prev.get('hp_after') is not None:
            try:
                prev_hp_after.append(float(prev.get('hp_after')))
            except Exception:
                pass

    # Estimate pressure level from yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    avg_prev_bid = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    # Base bid: aim to beat average but not chase peaks
    # Use supply to scale: with higher supply, lower competition.
    supply_mid = (MIN_SUPPLY + MAX_SUPPLY) / 2.0
    supply_factor = 1.0
    if supply > supply_mid:
        supply_factor = 0.92
    elif supply < supply_mid:
        supply_factor = 1.05

    # If someone previously bid very high, increase slightly; if my hp is low, increase more.
    pressure = 0.0
    if highest_prev_bid >= DAILY_SALARY * 1.7:
        pressure = 0.18
    elif highest_prev_bid >= DAILY_SALARY * 1.2:
        pressure = 0.10
    elif highest_prev_bid > 0:
        pressure = 0.06

    hp_boost = 0.0
    if my_hp <= 2:
        hp_boost = 0.28
    elif my_hp <= 4:
        hp_boost = 0.18
    elif my_hp <= 6:
        hp_boost = 0.10

    # Core target
    target = DAILY_SALARY * (0.66 + pressure + hp_boost) * supply_factor

    # If yesterday average was high, nudge toward it but cap below highest peak
    if avg_prev_bid > 0:
        target = max(target, avg_prev_bid * 0.92)

    # Cap: avoid runaway spending; also don't exceed budget.
    # Keep some budget for later days.
    budget_cap = my_budget * (0.55 if my_hp > 4 else 0.75)
    bid = min(target, budget_cap)

    # If supply is very low relative to requirement, ensure we bid at least a meaningful amount.
    if supply < WATER_REQ:
        bid = max(bid, DAILY_SALARY * 0.75)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)
